class Solution:
    def isValid(self, word: str) -> bool:
        # Check minimum length
        if len(word) < 3:
            return False

        vowels = set('aeiouAEIOU')
        has_vowel = False
        has_consonant = False

        for char in word:
            # Check if character is a valid type (digit or letter)
            if not char.isdigit() and not char.isalpha():
                return False

            # Check for vowels
            if char in vowels:
                has_vowel = True
            # Check for consonants (letters that are not vowels)
            elif char.isalpha():
                has_consonant = True

        return has_vowel and has_consonant
