class Solution:
    def numberOfSpecialChars(self, word: str) -> int:
        # Create a set of all characters present in the word for O(1) lookup
        chars = set(word)

        count = 0
        # Iterate through the lowercase letters 'a' to 'z'
        for char in 'abcdefghijklmnopqrstuvwxyz':
            # Check if the lowercase version exists and the uppercase version exists
            if char in chars and char.upper() in chars:
                count += 1

        return count
