class Solution:
    def clearDigits(self, s: str) -> str:
        stack = []
        for char in s:
            if char.isdigit():
                # If we encounter a digit, we must delete the digit itself
                # and the closest non-digit character to its left.
                # The stack stores the non-digit characters encountered so far.
                # The top of the stack is the closest non-digit to the left of the current digit.
                # The constraint guarantees that a non-digit always exists to the left of any digit.
                if stack:
                    stack.pop()
                # We do not push the digit onto the stack as it is removed.
            else:
                # If it's a non-digit character, push it onto the stack.
                stack.append(char)
        return "".join(stack)
```

