from typing import List

class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Initial position is cell 0, which corresponds to row 0, column 0
        row, col = 0, 0

        for command in commands:
            if command == "UP":
                row -= 1
            elif command == "DOWN":
                row += 1
            elif command == "LEFT":
                col -= 1
            elif command == "RIGHT":
                col += 1

        # The position is calculated as row * n + col
        return row * n + col
```

