class Solution:
    def countKConstraintSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        count = 0

        # Iterate over all possible substrings
        for i in range(n):
            zeros = 0
            ones = 0
            # Iterate over all end positions for the substring starting at i
            for j in range(i, n):
                if s[j] == '0':
                    zeros += 1
                else:
                    ones += 1

                # Check if the substring satisfies the k-constraint
                # Condition: (zeros <= k) OR (ones <= k)
                if zeros <= k or ones <= k:
                    count += 1

        return count
```

