class Solution:
    def minElement(self, nums: List[int]) -> int:
        def sum_digits(n: int) -> int:
            s = 0
            while n > 0:
                s += n % 10
                n //= 10
            return s

        min_val = float('inf')
        for num in nums:
            current_sum = sum_digits(num)
            if current_sum < min_val:
                min_val = current_sum

        return min_val
