from typing import List

class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)

        # Iterate through all valid starting positions for the first subarray
        # The first subarray starts at i, ends at i + k - 1
        # The second subarray starts at i + k, ends at i + 2k - 1
        # Valid i range: 0 to n - 2k
        for i in range(n - 2 * k + 1):
            # Check if the first subarray nums[i : i+k] is strictly increasing
            first_inc = True
            for j in range(i, i + k - 1):
                if nums[j] >= nums[j+1]:
                    first_inc = False
                    break

            if first_inc:
                # Check if the second subarray nums[i+k : i+2k] is strictly increasing
                second_inc = True
                for j in range(i + k, i + 2 * k - 1):
                    if nums[j] >= nums[j+1]:
                        second_inc = False
                        break

                if second_inc:
                    return True

        return False
