class Solution:
    def smallestNumber(self, n: int, t: int) -> int:
        x = n
        while True:
            product = 1
            has_zero = False
            temp = x
            while temp > 0:
                digit = temp % 10
                if digit == 0:
                    has_zero = True
                    break
                product *= digit
                temp //= 10

            if has_zero or product % t == 0:
                return x
            x += 1
