class Solution:
    def minAnagramLength(self, s: str) -> int:
        n = len(s)
        # Iterate through all possible lengths of t from 1 to n
        # Since t must be an anagram of parts of s, len(t) must divide len(s)
        for length in range(1, n + 1):
            if n % length == 0:
                # Check if s can be partitioned into chunks of 'length'
                # such that all chunks are anagrams of each other.

                # Get character counts for the first chunk
                counts = [0] * 26
                for i in range(length):
                    counts[ord(s[i]) - ord('a')] += 1

                is_valid = True
                # Check subsequent chunks
                for i in range(length, n, length):
                    chunk_counts = [0] * 26
                    for j in range(i, i + length):
                        chunk_counts[ord(s[j]) - ord('a')] += 1

                    # Compare counts
                    if chunk_counts != counts:
                        is_valid = False
                        break

                if is_valid:
                    return length
        return n
